"""CPU checks for the stable shader derivation. Device images are checked by validate.py."""
from pathlib import Path
import re
import tempfile
import unittest

import numpy as np

from preview_stable_lighting.shaders import configure_shaders


EXAMPLES = Path(__file__).resolve().parents[1]


def parent_sources(root):
    # Use the tracked shader templates and a minimal fragment representing
    # the three source hooks generated by the older sparse/compact builders.
    templates = {
        "resident_spatial.comp": "preview_compact/compact_reconstruct.comp",
        "preview_lowres.glsl": "preview_lowres_filter/lowres.glsl",
        "preview_history.comp": "preview_compact_history/history.comp",
        "preview_contour.glsl": "preview_contour_aa/contour.glsl",
    }
    sources = {name: (EXAMPLES / source).read_text(encoding="utf-8")
               for name, source in templates.items()}
    sources["resident_spatial.comp"] = '#include "preview_lowres.glsl"\n' + sources["resident_spatial.comp"]
    sources["resident.frag"] = '''#include "preview_sparse_common.glsl"
layout(location=0) out vec4 rgb;
layout(location=4) out vec4 compactAttributes;
#ifdef PR_PREVIEW_SPARSE_GUIDE
bool traced=u.counts.z!=0u&&shadingFacesView;
#endif
#ifdef PR_PREVIEW_SPARSE_MAIN
compactAttributes=vec4(shadingFacesView?sparseFallback(N):vec3(0.0),float(sparsePackNormal(N,false)));
rgb=vec4(color,float(sparsePackRho(rho)));
#endif
'''
    for name, source in sources.items():
        (root/name).write_text(source, encoding="utf-8")
    return sources


class StableShader(unittest.TestCase):
    def test_radius_control_preserves_primary_output_and_composes_own_environment(self):
        for radius, micrometres, rays in ((0, 0, 0), (.0249999, 25000, 10)):
            with self.subTest(radius=radius), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                before = parent_sources(root)
                policy = configure_shaders(root, radius)
                self.assertEqual((policy["ao_radius_um"], policy["max_ao_rays_per_diffuse_pixel"]),
                                 (micrometres, rays))
                self.assertEqual(policy["sparse_gi_proposals"], 0)
                self.assertFalse(policy["temporal_history"])
                for name in ("resident.frag", "resident_spatial.comp", "preview_contour.glsl"):
                    after = (root/name).read_text(encoding="utf-8")
                    # Resource bindings/output locations are the sealed parent's ABI.
                    interface = r"layout\([^)]*\b(?:binding|location)\s*=[^)]*\)[^\n]*"
                    self.assertEqual(re.findall(interface, after), re.findall(interface, before[name]))
                frag = (root/"resident.frag").read_text(encoding="utf-8")
                self.assertEqual(re.findall(r"^rgb=.*", frag, re.M), re.findall(r"^rgb=.*", before["resident.frag"], re.M))
                self.assertIn(f"PR_PREVIEW_AO_RADIUS_UM={micrometres}u", frag)
                self.assertRegex(frag, r"PR_PREVIEW_AO_RADIUS_UM>0u[^{}]+\{\s*environmentIncoming \*= stableEnvironmentVisibility\(")
                spatial = (root/"resident_spatial.comp").read_text(encoding="utf-8")
                stable = spatial.split("if(PR_PREVIEW_STABLE_LIGHTING_ABI==1u) {", 1)[1].split("} else {", 1)[0]
                self.assertRegex(stable, r"historyValue=vec4\(own.rgb,0.0\);\s*linear\+=rho\*own.rgb;")
                for name in ("preview_history.comp", "preview_contour.glsl"):
                    self.assertEqual((root/name).read_text(encoding="utf-8"), before[name])

    def test_rejects_parent_that_would_reuse_history_or_read_stale_contour(self):
        cases = (("preview_history.comp", "current.a==1.0", "current.a>=0.0"),
                 ("preview_contour.glsl", "nextHistory.pixels[", "previous.pixels["))
        for name, old, new in cases:
            with self.subTest(name=name), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                sources = parent_sources(root)
                (root/name).write_text(sources[name].replace(old, new), encoding="utf-8")
                original = {p.name: p.read_bytes() for p in root.iterdir()}
                with self.assertRaises(ValueError):
                    configure_shaders(root, .025)
                self.assertEqual({p.name: p.read_bytes() for p in root.iterdir()}, original)

    def test_antipodal_shader_directions_cover_sphere_symmetrically(self):
        shader = Path(__file__).with_name("stable_ao.glsl").read_text(encoding="utf-8")
        a, b = map(float, re.search(r"const float a = ([\d.]+), b = ([\d.]+);", shader).groups())
        constants = {"a": a, "-a": -a, "b": b, "-b": -b}
        entries = shader.split("const vec3 axes[10] = vec3[10](", 1)[1].split(");", 1)[0]
        triples = [line.split(",") for line in re.findall(r"vec3\(([^)]+)\)", entries)]
        axes = np.array([[constants[token] if token in constants else float(token) for token in triple]
                         for triple in triples])
        axes /= np.linalg.norm(axes, axis=1, keepdims=True)
        sphere = np.concatenate((axes, -axes))
        self.assertEqual(len(np.unique(sphere, axis=0)), 20)
        np.testing.assert_allclose(sphere.T @ sphere / 20, np.eye(3)/3, atol=1e-9)


if __name__ == "__main__":
    unittest.main()
